/// Applies shadow only on iOS 16+ for performance
struct ConditionalShadow: ViewModifier {
    let color: Color
    let radius: CGFloat
    let y: CGFloat
    
    func body(content: Content) -> some View {
        if PerformanceMode.current.useExpensiveEffects {
            content
                .shadow(color: color, radius: radius, y: y)
                .shadow(color: .black.opacity(0.15), radius: radius * 0.67, y: y * 0.67)
        } else {
            content
        }
    }
}

enum GlassIntensity {
    case clear
    case regular
    case prominent
    
    var material: Material {
        switch self {
        case .clear: return .ultraThinMaterial
        case .regular: return .ultraThinMaterial
        case .prominent: return .thinMaterial
        }
    }
    
    var opacity: Double {
        switch self {
        case .clear: return 0.7
        case .regular: return 0.85
        case .prominent: return 0.95
        }
    }
}

// MARK: - Enhanced Theme Colors


// MARK: - Immersive Background

struct LiquidGlassBackground: View {
    var accentColor: Color = GaryColors.gold
    var grainDensity: Double = 0.0012
    var grainOpacityRange: ClosedRange<Double> = 0.01...0.022

    var body: some View {
        GeometryReader { geo in
            ZStack {
                // Base: WARM near-black (R >= B) — the website's matte ink.
                // The old #090C11/#10161D charcoals had blue channels leading,
                // and the whole app sat on them: that was the grey-blue cast.
                Color(hex: "#0C0B0A")

                LinearGradient(
                    colors: [
                        Color(hex: "#151210"),
                        Color(hex: "#0B0A09")
                    ],
                    startPoint: .top,
                    endPoint: .bottom
                )

                // Single top glow for depth without muddying the lower half of the screen.
                RadialGradient(
                    colors: [
                        accentColor.opacity(0.11),
                        accentColor.opacity(0.025),
                        Color.clear
                    ],
                    center: UnitPoint(x: 0.5, y: 0.04),
                    startRadius: 24,
                    endRadius: geo.size.width * 0.92
                )

                // Edge darkening — cinematic vignette
                RadialGradient(
                    colors: [
                        Color.clear,
                        Color.black.opacity(0.32)
                    ],
                    center: .center,
                    startRadius: geo.size.width * 0.42,
                    endRadius: geo.size.width * 1.12
                )

                if grainDensity > 0 {
                    // A light texture pass for decorative screens; dense screens can opt out.
                    // SEEDED grain (perf pass, Jul 13): the old CGFloat.random redrew a
                    // DIFFERENT ~2.6k-dot pattern on every layout pass — the whole
                    // background shimmered each time content committed ("jumpy").
                    // A deterministic pattern per size renders identically every pass.
                    Canvas { context, size in
                        var rng = GrainRNG(state: UInt64(size.width) &* 7919 &+ UInt64(size.height))
                        let span = grainOpacityRange.upperBound - grainOpacityRange.lowerBound
                        for _ in 0..<Int(size.width * size.height * grainDensity) {
                            let x = rng.next() * size.width
                            let y = rng.next() * size.height
                            let opacity = grainOpacityRange.lowerBound + rng.next() * span
                            context.fill(
                                Path(CGRect(x: x, y: y, width: 1, height: 1)),
                                with: .color(.white.opacity(opacity))
                            )
                        }
                    }
                    .allowsHitTesting(false)
                }
            }
            // One GPU composite for the gradient stack + grain (no materials
            // inside, so drawingGroup is safe) — the background stops being
            // re-blended layer by layer on every content reflow.
            .drawingGroup()
        }
        .ignoresSafeArea()
    }

    /// SplitMix64 — tiny deterministic RNG for the grain pass.
    private struct GrainRNG {
        var state: UInt64
        mutating func next() -> CGFloat {
            state = state &+ 0x9E3779B97F4A7C15
            var z = state
            z = (z ^ (z >> 30)) &* 0xBF58476D1CE4E5B9
            z = (z ^ (z >> 27)) &* 0x94D049BB133111EB
            z = z ^ (z >> 31)
            return CGFloat(z >> 11) * (1.0 / 9007199254740992.0)
        }
    }
}

// MARK: - Obsidian Ground (Home only)

/// The infinite-depth layer WITHOUT leaving our black (founder, Aug 18: keep
/// the ink, keep the design — bring back the "space behind the app" feeling
/// the gold had). Ported from depth study 13 "OBSIDIAN": black glass whose
/// surface carries slow gold caustics — fourteen breathing filaments, each
/// stroked three times so it glows with zero blur filters. Rides ON TOP of
/// LiquidGlassBackground, so the base ink and vignette are untouched; this is
/// pure atmosphere at whisper opacity. Throttled to 20fps; freezes under
/// Reduce Motion.
struct ObsidianGround: View {
    @Environment(\.accessibilityReduceMotion) private var reduceMotion

    var body: some View {
        TimelineView(.animation(minimumInterval: 1.0 / 20.0, paused: reduceMotion)) { tl in
            Canvas { ctx, size in
                let time: Double = reduceMotion ? 0 : tl.date.timeIntervalSinceReferenceDate
                let W = size.width, H = size.height
                for i in 0..<14 {
                    let fi = Double(i)
                    let baseY = H * (0.05 + 0.068 * CGFloat(i))
                    var path = Path()
                    let steps = 72
                    for s in 0...steps {
                        let u = Double(s) / Double(steps)
                        let x = CGFloat(u) * W
                        let t1: Double = sin(u * 2.0 * .pi * 1.8 + time * 0.22 + fi * 0.9)
                        let t2: Double = sin(u * 2.0 * .pi * 3.7 - time * 0.16 + fi * 1.7)
                        let t3: Double = sin(u * 2.0 * .pi * 7.1 + time * 0.31 + fi * 2.6)
                        let wobble: Double = 0.018 * t1 + 0.011 * t2 + 0.0025 * t3
                        let y = baseY + H * CGFloat(wobble)
                        if s == 0 { path.move(to: CGPoint(x: x, y: y)) } else { path.addLine(to: CGPoint(x: x, y: y)) }
                    }
                    // Brightness swells and fades per filament on its own cycle.
                    // WHISPER level (first sim pass read as EKG lines through the
                    // panels): the layer must be felt, not read.
                    let pulse = 0.55 + 0.45 * sin(time * 0.12 + fi * 1.3)
                    ctx.stroke(path, with: .color(Color(hex: "#D9A62B").opacity(0.012 * pulse)), lineWidth: 8)
                    ctx.stroke(path, with: .color(Color(hex: "#D9A62B").opacity(0.020 * pulse)), lineWidth: 3.4)
                    ctx.stroke(path, with: .color(Color(hex: "#F2E4BC").opacity(0.030 * pulse)), lineWidth: 1.2)
                }
            }
        }
        .allowsHitTesting(false)
        .ignoresSafeArea()
    }
}


// MARK: - Depth-V3 Ground Studies (design/home-depth-v2 — NEVER merges)
// Round two, ported from the founder's reference implementation (the
// agent-run-apps infinite-hero lab): REAL 3D-rotated grid planes under
// perspective, flowing forever toward the viewer, at reference boldness —
// not hand-drawn fake perspective at whisper opacity. `ground N` flips live.
struct HomeGroundSwitcher: View {
    @State private var study: Int = UserDefaults.standard.integer(forKey: "garyGroundStudy")
    var body: some View {
        Group {
            switch study {
            case 1: DepthV3Floor()
            case 2: DepthV3Horizon()
            case 3: DepthV3Hall()
            case 4: DepthV3Wall()
            default: ObsidianGround()
            }
        }
        .onReceive(NotificationCenter.default.publisher(for: Notification.Name("GaryGroundStudy"))) { _ in
            study = UserDefaults.standard.integer(forKey: "garyGroundStudy")
        }
    }
}

private struct DepthV3Clock<Content: View>: View {
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    let content: (Double) -> Content
    var body: some View {
        TimelineView(.animation(minimumInterval: 1.0 / 30.0, paused: reduceMotion)) { tl in
            content(reduceMotion ? 2.0 : tl.date.timeIntervalSinceReferenceDate)
        }
        .allowsHitTesting(false)
        .ignoresSafeArea()
    }
}

/// The flat grid pattern that gets 3D-rotated into a plane. Horizontal lines
/// scroll by `phase` (the reference's background-position drift → the plane
/// flows toward the viewer forever); vertical lines converge via the actual
/// perspective transform.
private struct DepthV3GridPattern: View {
    let phase: CGFloat
    let spacingY: CGFloat
    let spacingX: CGFloat
    let alpha: Double

    var body: some View {
        Canvas { ctx, size in
            let gold = Color(hex: "#D9A62B")
            var y: CGFloat = -spacingY + phase.truncatingRemainder(dividingBy: spacingY)
            while y < size.height + spacingY {
                var p = Path()
                p.move(to: CGPoint(x: 0, y: y)); p.addLine(to: CGPoint(x: size.width, y: y))
                ctx.stroke(p, with: .color(gold.opacity(alpha)), lineWidth: 1.0)
                y += spacingY
            }
            var x: CGFloat = 0
            while x < size.width + spacingX {
                var p = Path()
                p.move(to: CGPoint(x: x, y: 0)); p.addLine(to: CGPoint(x: x, y: size.height))
                ctx.stroke(p, with: .color(gold.opacity(alpha * 0.85)), lineWidth: 1.0)
                x += spacingX
            }
        }
    }
}

// 1 — THE FLOOR: a full-width grid plane tilted away under the content,
// flowing toward the viewer forever. The classic infinite floor.
struct DepthV3Floor: View {
    var body: some View {
        DepthV3Clock { time in
            GeometryReader { geo in
                let W = geo.size.width, H = geo.size.height
                ZStack {
                    DepthV3GridPattern(phase: CGFloat(time * 34.0), spacingY: 64, spacingX: 76, alpha: 0.30)
                        .frame(width: W * 2.4, height: H * 0.9)
                        .rotation3DEffect(.degrees(62), axis: (x: 1, y: 0, z: 0), anchor: .top, perspective: 0.9)
                        .position(x: W * 0.5, y: H * 0.86)
                        .mask(
                            LinearGradient(stops: [
                                .init(color: .clear, location: 0),
                                .init(color: .black, location: 0.30),
                                .init(color: .black, location: 0.86),
                                .init(color: .clear, location: 1),
                            ], startPoint: .top, endPoint: .bottom)
                        )
                    // the horizon light the floor runs toward
                    RadialGradient(colors: [Color(hex: "#F2E4BC").opacity(0.14),
                                            Color(hex: "#D9A62B").opacity(0.05), .clear],
                                   center: .init(x: 0.5, y: 0.585), startRadius: 4, endRadius: W * 0.45)
                }
            }
        }
    }
}

