                        .frame(width: W * 2.6, height: H * 0.8)
                        .rotation3DEffect(.degrees(64), axis: (x: 1, y: 0, z: 0), anchor: .top, perspective: 0.85)
                        .rotation3DEffect(.degrees(-9), axis: (x: 0, y: 0, z: 1), anchor: .center, perspective: 0)
                        .position(x: W * 0.60, y: H * 0.80)
