                    Spacer(minLength: 0)
                } else if let error = error, settledCount == 0 {
                    Spacer(minLength: 0)
                    errorState(error: error)
                    Spacer(minLength: 0)
                } else {
                    ScrollView(showsIndicators: false) {
                        VStack(spacing: 26) {
