}

struct Signal: Identifiable {
    let id = UUID()
    let league: HubLeagueSel
    let kind: SignalKind
    let headline: String
    let detail: String
    let game: String
    let value: String
    let tone: HubTone
    var spark: [Double] = []
    var lineVal: Double? = nil
    /// BDL player id when the edge is player-backed — unlocks the full
    /// Player Insights breakdown from the card back.
    var playerId: String? = nil
    /// BDL team id when the edge is team-backed — routes to the team card
    /// (routing law, founder Jul 26: player tap = player card, team tap =
    /// team card; the small pop-up only when neither exists).
    var teamId: String? = nil
    /// "hit" / "miss" / "push" once graded (the Hub's morning receipts view).
    var result: String? = nil
    /// Grader's one-liner ("2-for-4, double") — the receipts row subline.
    var resultNote: String? = nil
    /// Structured player-swap payload (beneficiary lane) for the
    /// transaction-style OUT → IN row.
    var swap: SwapMeta? = nil
    /// Confirmed-XI payload (WC Confirmed XI lane) — both teams' team sheets,
    /// rendered as the formation + lineup beneath the edge.
    var confirmedXI: SwapMeta? = nil
    /// Regression payload (pitcher rows) — direction, ERA/xERA, peripherals and
    /// the verdict. `reg.day` ("tonight"/"tomorrow") splits the Regression Board.
    var reg: SwapMeta? = nil
    /// Head-to-head payload (head_to_head lane) — season series dominance + last meeting.
    var h2h: SwapMeta? = nil
    /// NRFI/YRFI payload — each side's recent first-inning sequence for the dots.
    var nrfi: SwapMeta? = nil
    /// The row's own EST slate day (insight_connections.date). Lets surfaces
    /// like the Regression Board re-anchor "Today"/"Tomorrow" against the
    /// CURRENT EST slate day (todayEST) instead of trusting a baked string,
    /// so a carried-forward row can never be mislabeled past the 6am rollover.
    var slateDate: String? = nil
    /// Live first-pitch park-weather payload (park_weather lane) — temp/wind/lean drive the MLB weather chip + sheet.
    var weather: SwapMeta? = nil
    var fantasy: SwapMeta? = nil   // fantasy-pickup payload (role / tier / ops / opp_sp)
    /// Player's field position ("2B", "SS", "LF"…) when the lane is player-backed —
    /// shown on the Insights row beside the matchup. Sourced from meta.position.
    var position: String? = nil
    /// The row's own game id (insight_connections.game_id, BDL id as string) —
    /// the doubleheader-safe attachment key: a game page only wears edges whose
    /// game id matches its own (Jul 22 2026, the Max Fried mixup).
    var gameId: String? = nil
    /// Football live-factor payload (`the_sweat`). It remains separate from
    /// generic edge detail so the game page can render the state compactly.
    var sweat: SwapMeta? = nil
    /// Exact same-book publish → latest verified pre-kick football receipt.
    /// Keeping this separate prevents the UI from parsing display prose back
    /// into market numbers or comparing Gary's number with a live-game line.
    var afterGary: SwapMeta? = nil
    /// Exact sportsbook low/high range for a football game. This remains
    /// separate from Gary's locked-number receipt and carries no bettor label.
    var marketRange: SwapMeta? = nil
    /// The next verified FBS slate on an honest NCAAF dark day.
    var nextSlate: SwapMeta? = nil
}

// MARK: - Picks Tab (per-game swipe carousel: Today's Top + game-by-game)
//
// Built on the SAME daily_picks data the board uses (PropsSlateStore — the
// 90-min run is untouched). Page 0 = "Today's Top" (the day's 2 highest-confidence
// props + top game pick + ranked edges). Pages 1..N = one matchup each (its 2
// props + game pick + that game's edges). Matchup filter bar + sport selector on
// top. Edges come from the real insight_connections — NO mock fallback; honest
// empty / "90-min" states instead.

/// A labeled list of edge cards (insight_connections), or a note when none exist yet.
struct EdgesSection: View {
    let title: String
    let edges: [Signal]
    var note: String = "More intel drops closer to game time."
    /// TODAY'S EDGES opts in: a category tab bar so the user can jump to a lane
    /// (Situational, Platoon Edge…) instead of scrolling the mixed feed. Off by
    /// default, so per-game GAME INTEL keeps its plain list.
    var tabbed: Bool = false
    @State private var selectedKind: SignalKind? = nil   // nil = THE SHOW

    /// Unique categories present, in first-appearance (feed) order.
    private var kinds: [SignalKind] {
        var seen = Set<SignalKind>(); var out: [SignalKind] = []
        for e in edges where !seen.contains(e.kind) { seen.insert(e.kind); out.append(e.kind) }
        return out
    }
    /// nil is THE SHOW: the full, mixed feed. A stale selection (for example
    /// after a sport switch removes that lane) also returns to THE SHOW instead
    /// of silently landing on whichever category happens to arrive first.
    private var activeKind: SignalKind? {
        if let k = selectedKind, kinds.contains(k) { return k }
        return nil
    }

    /// THE SHOW should feel like the whole slate, not one category followed by
    /// another category. Round-robin the live lanes while preserving the
    /// pipeline's ranking inside each lane.
    private var showMix: [Signal] {
        let buckets = kinds.map { kind in edges.filter { $0.kind == kind } }
        let longest = buckets.map(\.count).max() ?? 0
        return (0..<longest).flatMap { index in
            buckets.compactMap { index < $0.count ? $0[index] : nil }
        }
    }
    private var shown: [Signal] {
        guard let k = activeKind else { return showMix }
        return edges.filter { $0.kind == k }
    }
    // WC tags its venue/stadium intel as .ballpark; label it "VENUE" for soccer, not "Ballpark".
    private var isWC: Bool { edges.first?.league == .wc }

    var body: some View {
        VStack(alignment: .leading, spacing: 4) {
            // Title hidden when the category tabs are shown — redundant (user call).
            if !tabbed {
                Text(title)
                    .font(GaryFonts.mono(9.5, bold: true)).tracking(1)
                    .foregroundStyle(.white.opacity(0.62))
                    .pageGutter().padding(.top, 4)
            }
            if edges.isEmpty {
                Text(note)
                    .font(.system(size: 12)).foregroundStyle(.white.opacity(0.62))
                    .pageGutter().padding(.vertical, 8)
            } else {
                if tabbed && kinds.count > 1 { categoryTabBar }
                // (The ledger no longer renders from a list — it owns its own
                // section on the game page, GameH2HSection.)
                VStack(spacing: 0) { ForEach(shown) { SignalRow(s: $0) } }
                    .pageGutter()
            }
        }
    }

    /// Same mono font + icon + tint as the row category labels; gold underline
    /// marks the active filter (mirrors the matchup tab bar above the feed).
    private var categoryTabBar: some View {
        ScrollView(.horizontal, showsIndicators: false) {
            HStack(spacing: 22) {
                showTab
                ForEach(kinds, id: \.self) { categoryTab($0) }
                // Scroll affordance — there are more lanes off the right edge.
                if !kinds.isEmpty {
                    Image(systemName: "chevron.right")
                        .font(.system(size: 11, weight: .semibold))
                        .foregroundStyle(.white.opacity(0.25))
                        .padding(.bottom, 12)
                }
            }
            .pageGutter().padding(.top, 8).padding(.bottom, 2)
        }
    }

    private var showTab: some View {
        categoryTabLabel(icon: "sparkles", title: "THE SHOW", active: activeKind == nil) {
            selectedKind = nil
        }
    }

    @ViewBuilder
    private func categoryTab(_ kind: SignalKind) -> some View {
        categoryTabLabel(
            icon: kind.icon,
            title: (kind == .ballpark && isWC) ? "VENUE" : kind.chip,
            active: activeKind == kind
        ) {
            selectedKind = kind
        }
    }

    private func categoryTabLabel(icon: String, title: String, active: Bool,
                                  action: @escaping () -> Void) -> some View {
        Button { withAnimation(.easeInOut(duration: 0.18)) { action() } } label: {
            HStack(spacing: 6) {
                Image(systemName: icon).font(.system(size: 11, weight: .bold))
                Text(title).font(GaryFonts.mono(11.5, bold: true)).tracking(1.2)
            }
            .foregroundStyle(active ? GaryColors.gold : .white.opacity(0.45))
            .padding(.bottom, 11)
            .overlay(alignment: .bottom) {
                ZStack(alignment: .trailing) {
                    Capsule()
                        .fill(Color.white.opacity(active ? 0.10 : 0.045))
                        .frame(height: 1)
                    if active {
                        Capsule()
                            .fill(LinearGradient(
                                colors: [GaryColors.gold.opacity(0.42), GaryColors.gold, Color.white.opacity(0.78)],
                                startPoint: .leading, endPoint: .trailing))
                            .frame(height: 2.5)
                            .shadow(color: GaryColors.gold.opacity(0.35), radius: 2, y: 1)
                        Circle()
                            .fill(Color.white.opacity(0.9))
                            .frame(width: 3.5, height: 3.5)
                    }
                }
            }
        }
        .buttonStyle(.plain)
    }
}

/// MLB BDL team abbreviation -> name keywords, so insight_connections rows
/// (whose `game` is "DET @ TB") can be matched to slate matchups (full names).
let mlbTeamKeywords: [String: [String]] = [
